-- Platform-default UPI 3-way mappings (network file, bank switch, CBS ledger); tenants override per source.
INSERT INTO mapping_definition (tenant_id, source_id, version, rail, active, field_mappings, created_by)
VALUES ('*', 'network_settlement', 1, 'UPI', TRUE, '[{"canonicalField": "rrn", "sourceField": "rrn", "transformation": "DIRECT_COPY"}, {"canonicalField": "amountMinor", "sourceField": "amount", "transformation": "AMOUNT_TO_MINOR"}, {"canonicalField": "transactionTimeUtc", "sourceField": "txn_time", "transformation": "TIMESTAMP", "parameter": "yyyy-MM-dd''T''HH:mm:ssXXX"}, {"canonicalField": "direction", "sourceField": "dr_cr", "transformation": "VALUE_MAP", "parameter": "D=DEBIT,C=CREDIT,DEBIT=DEBIT,CREDIT=CREDIT", "defaultValue": "DEBIT"}, {"canonicalField": "transactionStatus", "sourceField": "status", "transformation": "VALUE_MAP", "parameter": "SUCCESS=SUCCESS,S=SUCCESS,FAILED=FAILED,F=FAILED,PENDING=PENDING,DEEMED=PENDING,REVERSED=REVERSED", "defaultValue": "UNKNOWN"}, {"canonicalField": "terminalId", "sourceField": "terminal_id", "transformation": "DIRECT_COPY"}, {"canonicalField": "merchantId", "sourceField": "merchant_id", "transformation": "DIRECT_COPY"}, {"canonicalField": "accountReference", "sourceField": "account", "transformation": "DIRECT_COPY"}, {"canonicalField": "utr", "sourceField": "utr", "transformation": "DIRECT_COPY"}]', 'system');
